        }
        return InterlockResult.pass();
    }

    private List<String> closedBreakers(String intervalId) {
        return jdbc.query(
                "SELECT device_id FROM device_state WHERE interval_id = ? AND device_type = 'BREAKER' AND state = 'CLOSED'",
